// Finanzen (ALLY 31, BA5, Stefan 20.10.2026): fünf Seiten aus dem Register – Belege (offene Fragen), Zeiterfassung, Monatsbericht, Projektbudgets, Kundenüberblick.
// Daten wie ALLY 8: ally_web_arbeit, arbeit_web_seite ('belege_verbuchen', 'budgets'), Kundschaft aus sync_mapping, Projekte aus Papierkram (PK 2), Budgets über ALLY 13.
// Aktionen mit Namen und Feldern von ALLY 8: start (was = belege, abgleich, kundenueberblick; kunde), klaerung (id, antwort), monatsbericht (projekt_id, monat,
// aufgaben_dl, projekt_label). Monatsbericht seit 24.10.2026 wieder mit Auswahl Kunde/Projekt wie vor dem 20.10. (Stefan 09:59). Liefert nur die Seitenbeschreibung (JSON).
// Karten Offen/Meldungen: Nebentext in den Text (schmale Karten neben dem Seitenfenster, sonst bricht der Text zeichenweise um)
// BA10 (Migration 69): Belege – Abschnitte „Beleg hochladen“ (Aktion be_hochladen, Datei an ALLY 20 POST app/datei) und „Belege mit Fehler“ (belege_fehler_ui),
// Original eines Belegs mit Fehler bzw. mit offener Frage über Ally (Seite „datei“, be=<id> bzw. kl=<id>, nie ein Direktlink; Rechte prüft die Datenbank).
// Kundenüberblick – Abschnitt „Letzte Überblicke“ (ally_ergebnisse_ui, nur eigene), Lesen im Seitenfenster (er=<id>), PDF über Seite „datei“ (er=<id>).
const knapp = u => { if (u && Array.isArray(u.karten)) for (const k of u.karten) for (const e of k.eintraege || []) if (e.neben) { e.text = String(e.text || '') + ' · ' + String(e.neben); delete e.neben; } return u; };
const E = $('Start').first().json;
const PA = $('Parameter').first().json || {};
const D = $('Daten laden').first().json || {};
const X = $('Arbeitsdaten laden (ALLY 13)').isExecuted ? ($('Arbeitsdaten laden (ALLY 13)').first().json || {}) : {};
const PK = $('Projekte laden (PK 2)').isExecuted ? ($('Projekte laden (PK 2)').first().json || {}) : null;
const F = E.funktion || {};
const P = E.parameter || {};
const SEITEN = ['belege', 'zeiterfassung', 'monatsbericht', 'projektbudgets', 'kundenueberblick'];
const seite = SEITEN.includes(String(E.seite || '')) ? String(E.seite) : 'belege';
const titel = String(F.name || seite);
const kopf = { schluessel: seite, art: 'funktion', titel, beschreibung: String(F.beschreibung || ''), krumen: [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: titel }] };
if (/^[a-z0-9-]{1,40}$/.test(String(F.einstellungen_ziel || ''))) kopf.zahnrad = { ziel: { seite: 'einstellungen', parameter: { bereich: String(F.einstellungen_ziel) } } };
const ende = (inhalt) => { knapp(inhalt.ueberblick); return [{ json: { inhalt: Object.assign({ seite: kopf }, inhalt) } }]; };
const hinweis = t => ende({ bloecke: [{ typ: 'hinweis', ton: 'warn', text: t }] });
if (D.ok !== true) return hinweis('Die Seite konnte nicht geladen werden. Bitte neu laden.');
const ZU = D.zustand || {};
const A = D.a || {};
const zahl = n => Number(n || 0).toLocaleString('de-DE');
const euro = v => v === null || v === undefined || v === '' ? '–' : Number(v).toLocaleString('de-DE', { style: 'currency', currency: 'EUR' });
const std = v => v === null || v === undefined || v === '' ? '–' : Number(v).toLocaleString('de-DE', { maximumFractionDigits: 1 }) + ' h';
const datumWert = s => { const m = /^(\d{2})\.(\d{2})\.(\d{4})/.exec(String(s || '')); return m ? m[3] + m[2] + m[1] : String(s || ''); };
const sortierung = (tab, erlaubt, std0, r0) => { const s = (ZU[seite + '.' + tab] || {}).sortierung || {};
  return { spalte: erlaubt.includes(s.spalte) ? s.spalte : std0, richtung: s.richtung === 'auf' || s.richtung === 'ab' ? s.richtung : r0 }; };
const sortiere = (liste, so, wert) => liste.map((z, i) => [z, i]).sort((a, b) => { const x = wert(a[0], so.spalte), y = wert(b[0], so.spalte);
  const c = typeof x === 'number' && typeof y === 'number' ? x - y : String(x ?? '').localeCompare(String(y ?? ''), 'de', { numeric: true }); return (so.richtung === 'ab' ? -c : c) || a[1] - b[1]; }).map(x => x[0]);
// Layout 13 (Plan 40): je = Zeilen je Seite, Vorgabe 20; Projektbudgets gibt 10 mit (wie die Anzeige, E8/E10), die übrigen Tabellen bleiben bei 20
const blatt = (tab, n, je = 20) => Math.min(Math.max(1, Math.ceil(n / je)), Math.max(1, Number((E.seiten || {})[tab]) || 1));
const tabelle = (id, t, spalten, liste, so, zeile, leer, je = 20) => { const bl = blatt(id, liste.length, je);
  return { typ: 'tabelle', id, titel: t, spalten, zeilen: liste.slice((bl - 1) * je, bl * je).map(zeile), sortierung: so, seite: bl, je_seite: je, gesamt: liste.length, leer }; };

// ---------- Belege: offene Fragen ----------
if (seite === 'belege') {
  const B = A.belege, W = D.b || {};
  if (!B || W.gebucht === false) return hinweis('Belege sind nicht eingerichtet.');
  const kl = Array.isArray(W.klaerungen) ? W.klaerungen : [];
  const GRUND = { lieferant_unklar: 'Lieferant unklar', kategorie_unklar: 'Angaben unsicher', moeglicher_duplikat: 'Möglicherweise doppelt', relevanz_unklar: 'Relevanz unklar', kein_anhang: 'Kein Anhang' };
  const neu = Number(B.neu) || 0, fe = Number(B.fehler) || 0;
  const FE = (Array.isArray(D.fe) ? D.fe : []).filter(x => x && /^[0-9]{1,12}$/.test(String(x.id)));
  const hier = (extra, anker) => ({ seite: 'belege', parameter: Object.assign({}, P.q ? { q: P.q } : {}, extra || {}), anker });
  const ueberblick = { kennzahlen: [
    { label: 'Neue Belege', wert: zahl(neu), neben: B.laeuft ? 'werden verbucht' : '' },
    { label: 'Offene Fragen', wert: zahl(kl.length), neben: '', ziel: kl.length ? hier({}, 'a-fragen') : undefined },
    { label: 'Mit Fehler', wert: zahl(fe), neben: fe ? 'bitte prüfen' : '', ton: fe ? 'warn' : '', ziel: FE.length ? hier({}, 'a-fehler') : undefined },
    { label: 'Stand', wert: B.laeuft ? 'läuft' : 'bereit', neben: '' }].map(k => { if (!k.ziel) delete k.ziel; return k; }),
    karten: [
      { titel: 'Offen', leer: 'Keine offenen Fragen.', eintraege: kl.slice(0, 5).map(k => ({ marke: { text: 'Frage', ton: 'warn' }, text: String(k.lieferant || k.absender || 'Beleg'),
        neben: [GRUND[k.grund], euro(k.betrag)].filter(Boolean).join(' · '), ziel: hier({ frage: k.id }, 'a-fragen'), ziel_text: 'Öffnen' })) },
      { titel: 'Meldungen', leer: 'Keine Meldungen.', eintraege: [].concat(B.laeuft ? [{ marke: { text: 'läuft', ton: 'info' }, text: 'Die Belege werden gerade verbucht.' }] : [],
        fe ? [Object.assign({ marke: { text: 'Fehler', ton: 'warn' }, text: zahl(fe) + (fe === 1 ? ' Beleg konnte nicht verbucht werden.' : ' Belege konnten nicht verbucht werden.') },
          FE.length ? { ziel: hier({}, 'a-fehler'), ziel_text: 'Ansehen' } : {})] : []) }] };
  const q = String(PA.q || '').toLowerCase();
  const liste = kl.filter(k => !q || [k.lieferant, k.absender, k.betreff].join(' ').toLowerCase().includes(q));
  const so = sortierung('fragen', ['beleg', 'betrag', 'datum', 'grund'], 'datum', 'ab');
  const wert = (k, sp) => sp === 'beleg' ? String(k.lieferant || k.absender || '').toLowerCase() : sp === 'betrag' ? Number(k.betrag || 0) : sp === 'datum' ? datumWert(k.datum) : String(GRUND[k.grund] || k.grund || '');
  const sel = PA.frage ? kl.find(k => String(k.id) === PA.frage) : null;
  const abschnitte = [{ id: 'fragen', titel: 'Offene Fragen', zahl: zahl(kl.length), offen_standard: true, inhalt: [
    { typ: 'filter', id: 'fragen', label: 'Fragen filtern', felder: [{ typ: 'suche', name: 'q', label: 'Suche', platzhalter: 'Lieferant, Absender, Betreff', wert: String(P.q || '').slice(0, 100) }] },
    tabelle('fragen', 'Offene Fragen', [{ schluessel: 'beleg', titel: 'Beleg', sortierbar: true }, { schluessel: 'betrag', titel: 'Betrag', sortierbar: true, ausrichtung: 'rechts' },
      { schluessel: 'datum', titel: 'Datum', sortierbar: true }, { schluessel: 'grund', titel: 'Grund', sortierbar: true }], sortiere(liste, so, wert), so,
      k => ({ aktiv: sel === k, zellen: { beleg: { text: String(k.lieferant || k.absender || 'Beleg'), ziel: hier({ frage: k.id }, 'a-fragen'), neben: String(k.betreff || '') },
        betrag: euro(k.betrag), datum: String(k.datum || ''), grund: { marke: { text: GRUND[k.grund] || 'Frage', ton: 'warn' } } } }), kl.length ? 'Keine Frage für diesen Filter.' : 'Keine offenen Fragen.')] }];
  // BA10: Belege mit Fehler (Tabelle, Original über Ally) und Beleg hochladen
  const soF = sortierung('fehler', ['beleg', 'eingang', 'zuletzt'], 'zuletzt', 'ab');
  const zeitWert = t => { const m = /^(\d{2})\.(\d{2})\.(\d{4})(?:\s+(\d{2}):(\d{2}))?/.exec(String(t || '')); return m ? m[3] + m[2] + m[1] + (m[4] || '00') + (m[5] || '00') : ''; };
  const wertF = (b, sp) => sp === 'beleg' ? String(b.lieferant || b.absender || '').toLowerCase() : zeitWert(sp === 'eingang' ? b.eingang : b.zuletzt);
  abschnitte.push({ id: 'fehler', titel: 'Belege mit Fehler', zahl: zahl(FE.length), offen_standard: FE.length > 0,
    info: 'Diese Belege konnten nicht verbucht werden. Ally versucht es beim nächsten Belege-Lauf erneut. Das Original lädt Ally aus dem Speicherort.',
    inhalt: [tabelle('fehler', 'Belege mit Fehler', [{ schluessel: 'beleg', titel: 'Beleg', sortierbar: true }, { schluessel: 'eingang', titel: 'Eingang', sortierbar: true },
      { schluessel: 'zuletzt', titel: 'Letzter Versuch', sortierbar: true }, { schluessel: 'grund', titel: 'Grund' }, { schluessel: 'datei', titel: 'Original' }], sortiere(FE, soF, wertF), soF,
      b => ({ zellen: { beleg: { text: String(b.lieferant || b.absender || 'Beleg'), fett: true, neben: [b.betreff, euro(b.betrag) !== '–' ? euro(b.betrag) : ''].filter(Boolean).join(' · ') },
        eingang: String(b.eingang || ''), zuletzt: { text: String(b.zuletzt || '–'), neben: Number(b.versuche) ? zahl(b.versuche) + (Number(b.versuche) === 1 ? ' Versuch' : ' Versuche') : '' },
        grund: String(b.grund || '–'), datei: b.datei ? { text: 'Herunterladen', ziel: { seite: 'datei', parameter: { be: String(b.id) } } } : '–' } }), 'Keine Belege mit Fehler.')] });
  abschnitte.push({ id: 'hochladen', titel: 'Beleg hochladen', zahl: '', offen_standard: false,
    info: 'PDF, E-Rechnung (XML) oder Foto (JPG, PNG, WEBP), höchstens 10 MB. Fotos werden in ein PDF umgewandelt. Der Beleg wird beim nächsten Belege-Lauf verbucht, sofort mit „Jetzt verbuchen“.',
    inhalt: [{ typ: 'formular', id: 'beleg-hochladen', aktion: 'be_hochladen', datei: true, felder: [{ typ: 'datei', name: 'datei', label: 'Beleg', pflicht: true, breite: 'voll', accept: '.pdf,.xml,image/jpeg,image/png,image/webp' }],
      knoepfe: [{ text: 'Hochladen' }] }] });
  const fenster = [];
  if (sel) fenster.push({ id: 'frage', art: 'seitenfenster', offen: true, titel: String(sel.lieferant || sel.absender || 'Beleg'), untertitel: GRUND[sel.grund] || '', schliessen_ziel: hier({}, 'a-fragen'), inhalt: [
    { typ: 'paare', eintraege: [{ label: 'Betrag', wert: euro(sel.betrag) }, { label: 'Datum', wert: String(sel.datum || '–') }, { label: 'Betreff', wert: String(sel.betreff || '–') },
      { label: 'Absender', wert: String(sel.absender || '–') }, { label: 'Seit', wert: String(sel.seit || '–') }] },
      { typ: 'aktion', text: 'Original herunterladen', label: 'Original herunterladen: ' + String(sel.lieferant || sel.absender || 'Beleg'), ziel: { seite: 'datei', parameter: { kl: String(sel.id) } } }]
    .concat(sel.text ? [{ typ: 'unterueberschrift', text: 'Frage' }, { typ: 'text', text: String(sel.text) }] : [], [
      { typ: 'formular', id: 'klaerung', aktion: 'klaerung', werte: { id: sel.id }, frage: 'Antwort zu dieser Frage senden? Der Beleg wird danach neu verbucht.',
        felder: [{ typ: 'textbereich', name: 'antwort', label: 'Antwort', pflicht: true, zeilen: 3, breite: 'voll', platzhalter: 'ja', hinweis: '„ja“ bestätigt den Vorschlag; „mache ich manuell“ oder „ist doppelt“; Korrekturen dazuschreiben.' }],
        knoepfe: [{ text: 'Antwort senden' }] }]) });
  if (neu && !B.laeuft) kopf.hauptaktion = { text: 'Jetzt verbuchen', aktion: 'start', werte: { was: 'belege' }, frage: 'Neue Belege jetzt verbuchen? Das dauert ein bis mehrere Minuten.' };
  return ende({ ueberblick, abschnitte, fenster });
}

// ---------- Zeiterfassung ----------
if (seite === 'zeiterfassung') {
  const Z = A.abgleich;
  if (!Z) return hinweis('Die Zeiterfassung ist nicht eingerichtet.');
  const ueberblick = { kennzahlen: [
    { label: 'Letzter Abgleich', wert: Z.zuletzt ? String(Z.zuletzt) : 'noch keiner', neben: Z.alt ? 'länger her als üblich' : '', ton: Z.alt ? 'warn' : '' },
    { label: 'Stand', wert: Z.laeuft ? 'läuft' : 'bereit', neben: '' }],
    karten: [
      { titel: 'Offen', leer: 'Nichts offen.', eintraege: Z.alt && !Z.laeuft ? [{ marke: { text: 'prüfen', ton: 'warn' }, text: 'Der letzte Abgleich ist länger her als üblich.' }] : [] },
      { titel: 'Meldungen', leer: 'Keine Meldungen.', eintraege: Z.laeuft ? [{ marke: { text: 'läuft', ton: 'info' }, text: 'Der Abgleich läuft gerade.' }] : [] }] };
  if (!Z.laeuft) kopf.hauptaktion = { text: 'Jetzt abgleichen', aktion: 'start', werte: { was: 'abgleich' }, frage: 'Jetzt abgleichen? Das dauert etwa eine Minute.' };
  return ende({ ueberblick });
}

// ---------- Projektbudgets ----------
if (seite === 'projektbudgets') {
  const W = D.w || {};
  if (!W.papierkram) return hinweis('Papierkram ist nicht eingerichtet.');
  const B = X.budgets || null;
  const projekte = B && Array.isArray(B.projekte) ? B.projekte : [];
  const hoch = projekte.filter(p => p.prozent !== null && p.prozent !== undefined && Number(p.prozent) >= 80);
  const beendet = projekte.filter(p => p.laufzeit_beendet);
  const anteil = p => p.prozent === null || p.prozent === undefined ? null : Number(p.prozent);
  const ueberblick = { kennzahlen: [
    { label: 'Projekte mit Budget', wert: B ? zahl(projekte.length) : '–', neben: B && B.stand ? 'Stand ' + String(B.stand) : '' },
    { label: 'Ab 80 % verbraucht', wert: zahl(hoch.length), neben: '', ton: hoch.length ? 'warn' : '' },
    { label: 'Laufzeit beendet', wert: zahl(beendet.length), neben: '', ton: beendet.length ? 'warn' : '' },
    { label: 'Grundlage', wert: B && B.grundlage ? String(B.grundlage) : 'Papierkram', neben: '' }],
    karten: [
      { titel: 'Offen', leer: 'Nichts offen.', eintraege: hoch.concat(beendet.filter(p => !hoch.includes(p))).slice(0, 5).map(p => ({ marke: { text: p.laufzeit_beendet ? 'beendet' : String(p.prozent).replace('.', ',') + ' %', ton: 'warn' },
        text: String(p.projekt || ''), neben: String(p.kunde || '') })) },
      { titel: 'Meldungen', leer: 'Keine Meldungen.', eintraege: !B ? [{ marke: { text: 'Fehler', ton: 'warn' }, text: 'Die Budgets konnten nicht geladen werden.' }]
        : B.fehler ? [{ marke: { text: 'Fehler', ton: 'warn' }, text: String(B.fehler) }] : [] }] };
  const so = sortierung('projekte', ['projekt', 'budget', 'verbraucht', 'anteil', 'rest'], 'anteil', 'ab');
  const geld = p => p.budget_art === 'Geld';
  const wert = (p, sp) => sp === 'projekt' ? String(p.projekt || '').toLowerCase() : sp === 'anteil' ? (anteil(p) ?? -1)
    : sp === 'budget' ? Number(geld(p) ? p.budget_eur : p.budget_stunden) || 0 : sp === 'verbraucht' ? Number(geld(p) ? p.verbraucht_eur : p.stunden) || 0 : Number(geld(p) ? p.rest_eur : p.rest_stunden) || 0;
  const abschnitte = [{ id: 'projekte', titel: 'Laufende Projekte mit Budget', zahl: zahl(projekte.length), offen_standard: true, inhalt: [
    tabelle('projekte', 'Laufende Projekte mit Budget', [{ schluessel: 'projekt', titel: 'Projekt', sortierbar: true }, { schluessel: 'budget', titel: 'Budget', sortierbar: true, ausrichtung: 'rechts' },
      { schluessel: 'verbraucht', titel: 'Verbraucht', sortierbar: true, ausrichtung: 'rechts' }, { schluessel: 'anteil', titel: 'Anteil', sortierbar: true, ausrichtung: 'rechts' },
      { schluessel: 'rest', titel: 'Rest', sortierbar: true, ausrichtung: 'rechts' }], sortiere(projekte, so, wert), so,
      p => ({ zellen: { projekt: { text: String(p.projekt || ''), fett: true, neben: [p.kunde, p.laufzeit_beendet ? 'Laufzeit beendet' : ''].filter(Boolean).join(' · ') },
        budget: geld(p) ? euro(p.budget_eur) : std(p.budget_stunden), verbraucht: geld(p) ? { text: euro(p.verbraucht_eur), neben: std(p.stunden) } : std(p.stunden),
        anteil: anteil(p) === null ? '–' : { marke: { text: String(p.prozent).replace('.', ',') + ' %', ton: anteil(p) >= 80 ? 'warn' : 'info' } },
        rest: geld(p) ? euro(p.rest_eur) : std(p.rest_stunden) } }), B ? (B.keine ? 'Keine laufenden Projekte mit Budget.' : 'Keine Projekte.') : 'Die Budgets konnten nicht geladen werden.', 10)] }];
  return ende({ ueberblick, abschnitte });
}

// ---------- Kundenüberblick ----------
if (seite === 'kundenueberblick') {
  const K = Array.isArray(A.kunden) ? A.kunden : null;
  if (!K) return hinweis('Der Kundenüberblick ist nicht eingerichtet.');
  const q = String(PA.q || '').toLowerCase();
  const liste = K.filter(k => !q || String(k.name || '').toLowerCase().includes(q));
  const so = sortierung('kundschaft', ['name'], 'name', 'auf');
  const ueberblick = { kennzahlen: [{ label: 'Kundschaft', wert: zahl(K.length), neben: 'aktiv in Papierkram' }],
    karten: [{ titel: 'Offen', leer: 'Nichts offen.', eintraege: [] }, { titel: 'Meldungen', leer: 'Keine Meldungen.', eintraege: [] }] };
  const abschnitte = [{ id: 'kundschaft', titel: 'Kundschaft', zahl: zahl(K.length), offen_standard: true, inhalt: [
    { typ: 'filter', id: 'kundschaft', label: 'Kundschaft suchen', felder: [{ typ: 'suche', name: 'q', label: 'Suche', platzhalter: 'Name', wert: String(P.q || '').slice(0, 100) }] },
    tabelle('kundschaft', 'Kundschaft', [{ schluessel: 'name', titel: 'Name', sortierbar: true }, { schluessel: 'aktion', titel: 'Überblick' }], sortiere(liste, so, k => String(k.name || '').toLowerCase()), so,
      k => ({ zellen: { name: { text: String(k.name || ''), fett: true }, aktion: { aktion: { text: 'Erstellen', aktion: 'start', werte: { was: 'kundenueberblick', kunde: String(k.id) },
        frage: 'Überblick zu „' + String(k.name || '') + '“ erstellen? Er kommt in den Chat und als PDF in den Speicherort.' } } } }), K.length ? 'Keine Kundschaft für diese Suche.' : 'Noch keine Kundschaft aus Papierkram übernommen.')] }];
  // BA10: letzte Überblicke der angemeldeten Person (Text im Seitenfenster, PDF über Ally)
  const UE = D.ue && D.ue.ok === true && Array.isArray(D.ue.liste) ? D.ue.liste.filter(x => x && /^[0-9]{1,12}$/.test(String(x.id))) : [];
  const hierU = extra => ({ seite: 'kundenueberblick', parameter: Object.assign({}, P.q ? { q: P.q } : {}, extra || {}), anker: 'a-ergebnisse' });
  const pdf = x => ({ seite: 'datei', parameter: { er: String(x.id) } });
  abschnitte.unshift({ id: 'ergebnisse', titel: 'Letzte Überblicke', zahl: zahl(UE.length), offen_standard: UE.length > 0,
    info: 'Deine letzten fünf Kundenüberblicke. Das PDF lädt Ally aus dem Speicherort. Ältere stehen unter Benachrichtigungen › Ergebnisse.',
    inhalt: [{ typ: 'liste', leer: 'Noch kein Kundenüberblick. Er erscheint hier, sobald einer erstellt wurde.',
      eintraege: UE.map(x => Object.assign({ text: String(x.titel || 'Kundenüberblick'), neben: String(x.zeit || ''), ziel: hierU({ er: String(x.id) }), ziel_text: 'Lesen' },
        x.datei ? { aktion: { text: 'PDF', label: 'PDF herunterladen: ' + String(x.titel || ''), ziel: pdf(x) } } : {})) }] });
  if (UE.length) ueberblick.kennzahlen.push({ label: 'Letzter Überblick', wert: String(UE[0].zeit || '–'), neben: String(UE[0].titel || '').replace(/^Kundenüberblick:\s*/, '') });
  const bausteine = t => { const aus = [];
    for (const abs of String(t || '').split(/\n{2,}/)) { const z = abs.split('\n').map(x => x.trim()).filter(Boolean); if (!z.length) continue;
      if (z.length === 1) { aus.push({ typ: 'text', text: z[0] }); continue; } let st = 0;
      if (/:$/.test(z[0]) || (z[0].length <= 60 && !/^[-•]/.test(z[0]))) { aus.push({ typ: 'unterueberschrift', text: z[0].replace(/:$/, '') }); st = 1; }
      aus.push({ typ: 'liste', eintraege: z.slice(st).map(x => ({ text: x.replace(/^[-•]\s*/, '') })) }); }
    return aus.length ? aus : [{ typ: 'text', ton: 'grau', text: 'Kein Text gespeichert.' }]; };
  const selU = PA.er ? UE.find(x => String(x.id) === PA.er) : null;
  const fenster = selU ? [{ id: 'ergebnis', art: 'seitenfenster', offen: true, titel: String(selU.titel || 'Kundenüberblick'), untertitel: String(selU.zeit || ''), schliessen_ziel: hierU({}),
    inhalt: bausteine(selU.text).concat(selU.datei ? [{ typ: 'aktion', text: 'PDF herunterladen', label: 'PDF herunterladen: ' + String(selU.datei_name || selU.titel || ''), ziel: pdf(selU) }] : []) }] : [];
  return ende({ ueberblick, abschnitte, fenster });
}

// ---------- Monatsbericht ----------
const kunden = Array.isArray(D.kunden) ? D.kunden : [];
const pkFehler = !PK || PK.error || !Array.isArray(PK.eintraege);
const projekte = pkFehler ? [] : PK.eintraege.filter(p => p && p.record_state === 'active');
const kName = {}; for (const k of kunden) kName[String(k.id)] = String(k.name || '');
const MON = ['Januar', 'Februar', 'März', 'April', 'Mai', 'Juni', 'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'];
const heute = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Berlin' }).format(new Date()).slice(0, 7);
const mPlus = (ym, n) => { const [y, m] = ym.split('-').map(Number); const d = y * 12 + (m - 1) + n; return Math.floor(d / 12) + '-' + String(d % 12 + 1).padStart(2, '0'); };
const vormonat = mPlus(heute, -1);
const datum = d => d ? String(d).slice(0, 10).split('-').reverse().join('.') : '';
const monate = p => { const st = p.start_date ? String(p.start_date).slice(0, 7) : null, en = p.end_date ? String(p.end_date).slice(0, 7) : null;
  if (st && en && st === en) return [];
  const a = st || String(p.created_at || heute).slice(0, 7); let b = en && en < heute ? en : heute; const out = [];
  for (let m = b; m >= a && out.length < 36; m = mPlus(m, -1)) out.push({ wert: m, text: MON[Number(m.slice(5)) - 1] + ' ' + m.slice(0, 4) });
  if (!out.length) out.push({ wert: a, text: MON[Number(a.slice(5)) - 1] + ' ' + a.slice(0, 4) }); return out; };
const budgetText = p => p.budget_type === 'money' && Number(p.budget_money) > 0 ? euro(p.budget_money) : p.budget_type === 'working_time' && Number(p.budget_time) > 0 ? String(Number(p.budget_time)).replace('.', ',') + ' Stunden' : 'ohne Budget';
const zeitraum = p => p.start_date && p.end_date ? datum(p.start_date) + ' – ' + datum(p.end_date) : p.start_date ? 'ab ' + datum(p.start_date) : 'ohne Zeitraum';
// Stefan 24.10.2026, 09:59: „wieder Dropdowns wie vorher. Keine Listen“ – Aufbau wie vor dem 20.10. (ALLY 8): Auswahl Kunde, Auswahl Projekt (nur Projekte des Kunden),
// Zeitraum und Budget des Projekts, Monat (nur bei Projekten über mehrere Monate, Vorgabe Vormonat), Dienstleistungen der Aufgaben, „Bericht erstellen“.
// Desktop (E12, Koordinator 24.10.): Kunde | Projekt, darunter Monat | Zeitraum und Budget (Anzeige); keine Ausklappliste über die volle Breite. Handy untereinander.
// Nur aktive Projekte aktiver Kunden. Bericht über denselben Weg wie bisher (Aktion monatsbericht: projekt_id, monat, aufgaben_dl, projekt_label = Kunde · Projekt · Monat).
const gruppen = {};
for (const p of projekte) { const kn = kName[String(p.company_id)]; if (kn) (gruppen[String(p.company_id)] = gruppen[String(p.company_id)] || []).push(p); }
const kIds = Object.keys(gruppen).sort((a, b) => kName[a].localeCompare(kName[b], 'de'));
for (const k of kIds) gruppen[k].sort((a, b) => String(b.start_date || '').localeCompare(String(a.start_date || '')) || String(a.name || '').localeCompare(String(b.name || ''), 'de'));
const alleP = kIds.flatMap(k => gruppen[k]);
const ER = D.erg && typeof D.erg === 'object' ? D.erg : null;
const abschnitte = [];
// Ergebnis des letzten Berichts (einmalig) wie vorher
if (ER) abschnitte.push(ER.ok
  ? { id: 'ergebnis', titel: 'Bericht erstellt', inhalt: [{ typ: 'text', ton: 'grau', text: String(ER.titel || '') + ' für ' + String(ER.kunde || '') + ' · ' + String(ER.projekt || '') },
    { typ: 'paare', eintraege: [{ label: 'Datei', wert: String(ER.datei || '') }, { label: 'Ablage', wert: String(ER.ablage || '') }, { label: 'Zeitraum', wert: String(ER.zeitraum || '') },
      { label: 'Zeiteinträge', wert: String(ER.eintraege ?? '') }, { label: 'Erfasste Zeit', wert: String(ER.zeit || '') + ' h (' + String(ER.stunden ?? '') + ' Std.)' }, { label: 'Summe netto', wert: String(ER.betrag || '') }]
      .concat(ER.aufgaben_dl ? [{ label: 'Stundensätze (je Aufgabe)', wert: String(ER.preis || '') }] : [], ER.verbraucht_bisher ? [{ label: 'Verbraucht bis Monatsende', wert: String(ER.verbraucht_bisher) }] : [],
        ER.rest ? [{ label: ER.ueber_budget ? 'Über Budget' : 'Restbudget', wert: String(ER.rest) }] : []) }] }
  : { id: 'ergebnis', titel: 'Bericht nicht erstellt', inhalt: (ER.label ? [{ typ: 'text', ton: 'grau', text: String(ER.label) }] : []).concat([{ typ: 'hinweis', ton: 'warn', text: 'Grund: ' + String(ER.grund || '') }]) });
if (pkFehler) abschnitte.push({ id: 'erstellen', titel: 'Monatsbericht erstellen', inhalt: [{ typ: 'hinweis', ton: 'warn', text: 'Die Projektliste aus Papierkram konnte nicht geladen werden. '
  + String((PK && PK.error && (PK.error.message || PK.error)) || 'Unbekannter Fehler.') + ' Bitte die Seite später neu laden.' }] });
else {
  const ids = alleP.map(p => String(p.id));
  abschnitte.push({ id: 'erstellen', titel: 'Monatsbericht erstellen', kachel: false, info: 'Vor dem Bericht werden die Zeiten aus timeBuzzer nach Papierkram übertragen. Läuft ein Projekt über mehrere Monate, zeigt der Bericht die Zeiten des gewählten Monats und den Budgetverbrauch bis Monatsende. Dienstleistungen der Aufgaben: nur nötig, wenn eine Aufgabe in Papierkram eine eigene Dienstleistung hat; kostet je Aufgabe einen Papierkram-Abruf.',
    inhalt: [{ typ: 'text', ton: 'grau', text: 'Zeiten aus Papierkram als PDF im Speicherort.' }]
    .concat(alleP.length ? [] : [{ typ: 'text', text: 'Keine aktiven Projekte gefunden.' }])
    .concat([{ typ: 'formular', id: 'monatsbericht', aktion: 'monatsbericht', spalten: 2, knopf_erst_wenn_pflicht: true,
      frage: 'Monatsbericht jetzt erstellen? Das dauert etwa eine halbe Minute. Bitte die Seite offen lassen.',
      felder: [
        { typ: 'auswahl', name: 'kunde', label: 'Kunde', ausklappliste: true, wert: '', optionen: [{ wert: '', text: 'Kunde wählen' }].concat(kIds.map(k => ({ wert: k, text: kName[k] }))) },
        { typ: 'auswahl', name: 'projekt_id', label: 'Projekt', pflicht: true, ausklappliste: true, abhaengig_von: 'kunde', leer_text: 'Erst Kunde wählen', wert: '',
          optionen: kIds.flatMap(k => (gruppen[k].length > 1 ? [{ wert: '', text: 'Projekt wählen', gruppe: k }] : [])
            .concat(gruppen[k].map(p => ({ wert: String(p.id), text: String(p.name || ''), gruppe: k, standard: gruppen[k].length === 1 })))) },
        { typ: 'auswahl', name: 'monat', label: 'Monat', ausklappliste: true, hoehe: 2, abhaengig_von: 'projekt_id', info: 'Zeiten des Monats, Budget bis Monatsende', wert: '', zeigen_wenn: { feld: 'projekt_id', werte: ids },
          optionen: alleP.flatMap(p => { const mo = monate(p); const v = mo.some(m => m.wert === vormonat) ? vormonat : (mo[0] || {}).wert; return mo.map(m => ({ wert: m.wert, text: m.text, gruppe: String(p.id), standard: m.wert === v })); }) },
        { typ: 'anzeige', name: 'zeitraum_anzeige', label: 'Zeitraum', je_wert: { feld: 'projekt_id', werte: Object.fromEntries(alleP.map(p => [String(p.id), zeitraum(p)])) }, zeigen_wenn: { feld: 'projekt_id', werte: ids } },
        { typ: 'anzeige', name: 'budget_anzeige', label: 'Budget', je_wert: { feld: 'projekt_id', werte: Object.fromEntries(alleP.map(p => [String(p.id), budgetText(p)])) }, zeigen_wenn: { feld: 'projekt_id', werte: ids } },
        { typ: 'haken', name: 'aufgaben_dl', label: 'Dienstleistungen der Aufgaben berücksichtigen', neben: 'Nur bei eigener Dienstleistung je Aufgabe', wert_an: 'ja', zeigen_wenn: { feld: 'projekt_id', werte: ids } },
        { typ: 'versteckt', name: 'projekt_label', aus_feldern: ['kunde', 'projekt_id', 'monat'] }],
      knoepfe: [{ text: 'Bericht erstellen' }] }]) });
}
return ende({ abschnitte });

// Parameter (ALLY 31, Finanzen: belege, zeiterfassung, monatsbericht, projektbudgets, kundenueberblick): Sitzung, Seite (nur die fünf eigenen),
// gewählte Kundschaft (Papierkram-ID, nur Ziffern), gewähltes Projekt (nur Ziffern), gewählte offene Frage (nur Ziffern), Suchbegriff (bis 100 Zeichen).
// BA10: gewählter Kundenüberblick (er, nur Ziffern).
const E = $input.first().json;
const P = E.parameter || {};
const S = ['belege', 'zeiterfassung', 'monatsbericht', 'projektbudgets', 'kundenueberblick'];
const seite = S.includes(String(E.seite || '')) ? String(E.seite) : 'belege';
const nr = v => /^[0-9]{1,12}$/.test(String(v || '')) ? String(v) : '';
return [{ json: { werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : '', seite], seite, kunde: nr(P.kunde), projekt: nr(P.projekt), frage: nr(P.frage), er: nr(P.er),
  q: String(P.q || '').replace(/[\x00-\x1f\x7f]/g, ' ').trim().slice(0, 100) } }];
